import math

class Solution:
    def getMinDistSum(self, positions: list[list[int]]) -> float:
        def dist_sum(x, y):
            return sum(math.hypot(x - px, y - py) for px, py in positions)
        x = sum(p[0] for p in positions) / len(positions)
        y = sum(p[1] for p in positions) / len(positions)
        step = 50.0
        eps = 1e-7
        while step > eps:
            improved = False
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = x + dx * step, y + dy * step
                if dist_sum(nx, ny) < dist_sum(x, y):
                    x, y = nx, ny
                    improved = True
                    break
            if not improved:
                step /= 2.0
        return dist_sum(x, y)

class Solution {
    double distSum(double x, double y, const vector<vector<int>>& positions) {
        double d = 0;
        for (const auto& p : positions) {
            d += hypot(x - p[0], y - p[1]);
        }
        return d;
    }
public:
    double getMinDistSum(vector<vector<int>>& positions) {
        double x = 0, y = 0;
        for (const auto& p : positions) {
            x += p[0];
            y += p[1];
        }
        x /= positions.size();
        y /= positions.size();
        double step = 50.0;
        double eps = 1e-7;
        const int dirs[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        while (step > eps) {
            bool improved = false;
            double curD = distSum(x, y, positions);
            for (int i = 0; i < 4; i++) {
                double nx = x + dirs[i][0] * step;
                double ny = y + dirs[i][1] * step;
                if (distSum(nx, ny, positions) < curD) {
                    x = nx;
                    y = ny;
                    improved = true;
                    break;
                }
            }
            if (!improved) step /= 2.0;
        }
        return distSum(x, y, positions);
    }
};

